def split_csv(line):
    n = len(line)
    if n == 0:
        return [""]

    fields = []
    i = 0
    while True:
        if i < n and line[i] == '"':
            i += 1
            field_chars = []
            while True:
                if i >= n:
                    return None  # unterminated quoted field
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        field_chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        break
                else:
                    field_chars.append(c)
                    i += 1
            # after closing quote must be comma or end of line
            if i < n and line[i] != ',':
                return None
            fields.append(''.join(field_chars))
            if i < n and line[i] == ',':
                i += 1
                continue
            else:
                break
        else:
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
                continue
            else:
                break

    return fields

